function timePicker(name,value='20:00'){let a=(value||'20:00').split(':'),h=a[0]||'20',m=a[1]||'00';return '<div class="timepicker"><div class="timefield"><span>'+h+'</span><select name="'+name+'_h" onchange="this.previousElementSibling.textContent=this.value">'+Array.from({length:24},(_,i)=>{let v=String(i).padStart(2,'0');return '<option '+(v===h?'selected':'')+'>'+v+'</option>'}).join('')+'</select></div><b>:</b><div class="timefield"><span>'+m+'</span><select name="'+name+'_m" onchange="this.previousElementSibling.textContent=this.value">'+Array.from({length:60},(_,i)=>{let v=String(i).padStart(2,'0');return '<option '+(v===m?'selected':'')+'>'+v+'</option>'}).join('')+'</select></div></div>'}function getPickedTime(f,name){return f.get(name+'_h')+':'+f.get(name+'_m')}
