function taskCard(t){let pct=t.need?Math.min(100,Math.round(t.done/t.need*100)):0,people=[...new Set((t.history||[]).map(x=>x.nick))];return '<div class="item taskclick" onclick="taskDetails('+t.id+',event)"><div class="itemtop"><div><h3>'+esc(t.title)+'</h3><div class="muted">'+(t.need?('Нужно: '+t.need+' '+unitForm(t.need,t.unit)+' · Собрано: <b class="acid">'+t.done+'</b> '+unitForm(t.done,t.unit)):'Без количества')+(t.place?' · '+esc(t.place):'')+'</div></div><span class="badge taskstatus '+(t.status==='Выполнено'||t.status==='Выполнена'?'done':'open')+'">'+esc(t.status==='Открыта'?'В процессе':t.status)+'</span></div>'+(t.need?'<div class="progress"><i style="width:'+pct+'%"></i></div><small class="muted">'+pct+'% выполнено</small>':'')+'<div class="muted" style="margin-top:8px">'+(t.deadline?('До: '+esc(t.deadline)):'')+'</div>'+(people.length?'<div style="margin-top:8px"><small class="muted">Участники:</small><div class="presence" style="margin-top:6px">'+people.map(n=>'<span class="badge work">'+esc(n)+'</span>').join(' ')+'</div></div>':'')+(t.comment?'<div style="margin-top:6px">'+esc(t.comment)+'</div>':'')+'<div class="actions">'+(t.need?'<button onclick="event.stopPropagation();addContribution('+t.id+')">+ Добавить количество</button>':'')+((t.creator===db.profile.nick||db.profile.access==='admin')?'<button onclick="event.stopPropagation();editTask('+t.id+')">Редактировать</button>':'')+(db.profile.access==='admin'?'<button class="danger" onclick="event.stopPropagation();deleteTask('+t.id+')">Удалить</button>':'')+'</div></div>'}
