function formatPlanDate(d){if(!d)return'';let p=d.split('-');return p.length===3?p[2]+'.'+p[1]+'.'+p[0]:d}
function ops(){$('#view').innerHTML='<div class="card"><div class="toolbar"><div><h2>План на рейд</h2><span class="muted">Создать общий план отряда на выбранную дату и время.</span></div><button class="primary" onclick="newOp()">+ СОЗДАТЬ ПЛАН</button></div><div class="list">'+(db.ops.length?db.ops.map(o=>{let p=Array.isArray(o.participants)?o.participants:[];return '<div class="item raiditem raidclick" onclick="viewOp('+o.id+')"><div class="itemtop"><div style="flex:1"><h3>'+esc(o.title)+'</h3><div class="muted">'+(o.date?formatPlanDate(o.date)+' · ':'')+esc(o.time)+(o.note?' · '+esc(o.note):'')+'</div></div><span class="badge">'+p.length+' участников</span></div><div style="margin-top:10px"><small class="muted">Участники:</small><div class="presence" style="margin-top:6px">'+(p.length?p.map(n=>'<span class="badge work">'+esc(n)+'</span>').join(' '):'<span class="muted">Пока никто не записался</span>')+'</div></div><div class="actions"><button onclick="event.stopPropagation();toggleRaid('+o.id+')">'+(p.includes(db.profile.nick)?'Не участвую':'Участвую')+'</button><button onclick="event.stopPropagation();editOp('+o.id+')">Редактировать</button><button onclick="event.stopPropagation();deleteOp('+o.id+')">Удалить</button></div></div>'}).join(''):'<div class="empty">Планов пока нет</div>')+'</div></div>'}
